export const TAGS_NAME_MPM: Record<string, string> = {
  '01': 'QR Type',
  '26/01': 'aliasNm',
  '26/02': 'bankCd',
  '26/03': 'placeId',
  '59': 'placeNm',
  '62/00': 'GUI',
  '62/50': 'txCode',
  //서브태그 추가 가능
};

export function getTagNameMPM(tag: string): string {
  return EMV_TAGS_MPM[tag]?.name || 'Unknown Tag';
}

export function formatValueHexMPM(hex: string): string {
  // For MPM, the value is already in plain text, not hex
  // Just return as-is
  return hex;
}

export function decodeTagValueMPM(tag: string, value: string): string {
  const info = EMV_TAGS_MPM[tag];
  if (!info || !value) return '';

  // For MPM, values are already in plain text format
  // Just return the value as-is for most cases

  if (tag === '53') {
    // Transaction Currency - ISO 4217 code
    // Could add currency code lookup here
    return value; // e.g., "410" for KRW
  }

  if (tag === '58') {
    // Country Code - ISO 3166-1
    return value; // e.g., "KR"
  }

  // For most MPM tags, the value is already human-readable
  return value;
}
