import { memo } from 'react';
import { useStore } from '~/app/store/store';
import { ScannerType } from '~/entities/qr-scan/model/types';
import {
  ManualInputContainer,
  ManualInputPressAbleButton,
  ManualMessageSubText,
  ManualMessageText,
} from '~/entities/qr-scan/ui/styled';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const QrScanManualInput = memo(function QrScanManualInput() {
  const { navigate } = useNavigate();
  const scannerType = useStore((state) => state.qrScannerSlice.options.scannerType);
  const text = scannerType === ScannerType.PaymentQRScan ? i18n.t('directInputPayment') : i18n.t('directInputTransfer');

  const handleManualInput = () => {
    navigate(PATHS.inputTransactionNumber);
  };
  return (
    <ManualInputContainer>
      <ManualMessageText>{i18n.t('scanNotWorking')}</ManualMessageText>
      <ManualInputPressAbleButton onClick={handleManualInput}>
        <ManualMessageSubText>{text}</ManualMessageSubText>
      </ManualInputPressAbleButton>
    </ManualInputContainer>
  );
});
