import { memo } from 'react';
import { QRScanScgMaskProp } from '~/entities/qr-scan/model/types';
import { SvgMaskContainer, SvgMaskCornerContainer, SvgMaskImage } from '~/entities/qr-scan/ui/styled';
import BottomLeftSvg from '~/shared/assets/img/qrcode/qr-bl-corner.svg';
import BottomRightSvg from '~/shared/assets/img/qrcode/qr-br-corner.svg';
import TopLeftSvg from '~/shared/assets/img/qrcode/qr-tl-corner.svg';
import TopRightSvg from '~/shared/assets/img/qrcode/qr-tr-corner.svg';

export const QrScanSvgMask = memo(function QrScanSvgMask({ height, width, children }: QRScanScgMaskProp) {
  const squareSize = width * 0.6;
  const maskTop = (height - width) / 2;
  const maskLeft = (width - squareSize) / 2;
  const borderRadius = 10;
  return (
    <>
      <SvgMaskCornerContainer $top={maskTop} $left={maskLeft} $px={squareSize}>
        <SvgMaskImage className="corner top-left" src={TopLeftSvg} />
        <SvgMaskImage className="corner top-right" src={TopRightSvg} />
        <SvgMaskImage className="corner bottom-left" src={BottomLeftSvg} />
        <SvgMaskImage className="corner bottom-right" src={BottomRightSvg} />
        {children ?? children}
      </SvgMaskCornerContainer>
      <SvgMaskContainer>
        <svg height={height} width={width}>
          <defs>
            <mask id="mask">
              <rect x="0" y="0" width={width} height={height} fill="white" />
              <rect
                x={maskLeft}
                y={maskTop}
                width={squareSize}
                height={squareSize}
                rx={borderRadius}
                ry={borderRadius}
                fill="black"
              />
            </mask>
          </defs>
          <rect x="0" y="0" width={width} height={height} fill="rgba(0,0,0,0.7)" mask="url(#mask)" />
        </svg>
      </SvgMaskContainer>
    </>
  );
});
