import { getOSByUserAgent } from '@toss/utils';
import QrScanner from 'qr-scanner';

export const getBackCamera = async (): Promise<MediaDeviceInfo | null> => {
  const devices = await navigator?.mediaDevices?.enumerateDevices();
  const videoDevices = devices.filter((device) => device.kind === 'videoinput');
  return videoDevices.length > 0 ? videoDevices[videoDevices.length - 1] : null;
};

export const setBackCameraForAndroid = async (scanner: QrScanner) => {
  if (getOSByUserAgent() !== 'android') {
    // console.log('set back camera is only for Android');
    return;
  }
  if (!scanner) {
    console.error('Scanner is not initialized');
    return;
  }
  const backCamera = await getBackCamera();
  if (!backCamera?.deviceId) {
    console.error('Back camera is not found');
    return;
  }

  await scanner.setCamera(backCamera?.deviceId);
  // console.log('Back camera set for Android');
};
