export const checkCameraPermission = async () => {
  if (window.ReactNativeWebView) {
    // Android Webview does not support navigator.permissions
    return true;
  }
  try {
    const permissionStatus = await navigator.permissions.query(<PermissionDescriptor>(<unknown>{ name: 'camera' }));
    if (permissionStatus.state === 'granted') {
      return true;
    } else if (permissionStatus.state === 'prompt') {
      let stream: MediaStream | null = null;
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: true });
        return true;
      } catch (e) {
        console.error('User denied camera access:', e);
        return false;
      } finally {
        stream?.getTracks().forEach((track) => track.stop());
      }
    } else {
      return false;
    }
  } catch (e) {
    console.error('Error checking camera permission:', e);
    return false;
  }
};
