import { TAGS_NAME_MPM } from '~/entities/qr-code/lib/emvTagsMPM';
import type { AllQRCode, ParsedItems } from '~/entities/qr-code/model/types';
import { determineProperty } from '~/entities/qr-scan/lib/determine-property';
import { parseQRCodeItems } from '~/entities/qr-scan/lib/parse-qr-code';
import { validateParsedData } from '~/entities/qr-scan/lib/validate-parsed-data';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { MPMQrScanType } from '~/shared/api/dtos/enums';

export type InvalidQRScanReason = 'parse' | 'scanner-type' | 'validation';

type QRScanResolution = { status: 'success'; data: AllQRCode } | { status: 'invalid'; reason: InvalidQRScanReason };

const findValue = (items: ParsedItems, tag: string) =>
  items.find((item) => item.name === TAGS_NAME_MPM[tag])?.value ?? '';

const resolveEmvData = (items: ParsedItems): AllQRCode => {
  const mpmType = findValue(items, '01');

  if (mpmType === MPMQrScanType.변동형) {
    return {
      mpmType,
      txCode: findValue(items, '62/50'),
    };
  }

  if (mpmType === MPMQrScanType.고정형) {
    return {
      mpmType,
      aliasNm: findValue(items, '26/01'),
      bankCode: findValue(items, '26/02'),
      placeId: findValue(items, '26/03'),
      placeNm: findValue(items, '59'),
    };
  }

  return {};
};

export const resolveQRScanResult = (decodedText: string, scannerType?: ScannerType): QRScanResolution => {
  const parsedQRCode = parseQRCodeItems(decodedText);
  if (!parsedQRCode) {
    return { status: 'invalid', reason: 'parse' };
  }

  if (!scannerType) {
    return { status: 'invalid', reason: 'scanner-type' };
  }

  const qrData = parsedQRCode.format === 'json' ? parsedQRCode.data : resolveEmvData(parsedQRCode.data);
  const property = determineProperty(scannerType);
  if (!property || !validateParsedData(qrData, property)) {
    return { status: 'invalid', reason: 'validation' };
  }

  return { status: 'success', data: qrData };
};
