import { AllQRCode, Item } from '~/entities/qr-code/model/types';
import { MPMQrScanType } from '~/shared/api/dtos/enums';

export const validateParsedData = (data: AllQRCode, property: keyof AllQRCode): boolean => {
  if (data.mpmType === MPMQrScanType.고정형) {
    return property === 'txCode' && !!data?.['aliasNm'] && (data['aliasNm']?.length ?? 0) > 0;
  }

  return !!data?.[property] && (data[property]?.length ?? 0) > 0;
};

export const validateParsedEmvData = (data: Item[], property: keyof AllQRCode): boolean => {
  const item = data.find((i) => i.name === property);
  return !!item && (item.value?.length ?? 0) > 0;
};
