import { ErrorBoundary, Suspense } from '@suspensive/react';
import { useState } from 'react';
import { useStore } from '~/app/store/store';
import { CameraErrorFallback } from '~/pages/qr-scan/camera-error-fallback';
import { QRScanCamera } from '~/pages/qr-scan/qr-scan-camera';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { WebViewRedirectionBoundary } from '~/widgets/web-view/redirection-boundary';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { QrScanGuide } from '~/entities/qr-scan/ui/qr-scan-guide';
import { QrScanContainer } from '~/entities/qr-scan/ui/styled';
import i18n from '~/shared/i18n/i18n';

export const QrScanPage = () => {
  const scannerType = useStore((state) => state.qrScannerSlice.options.scannerType);
  const title = scannerType === ScannerType.PaymentQRScan ? i18n.t('qrPayment') : i18n.t('qrScan');
  useSetHeaderTitle(title);
  const [resetCounter, setResetCounter] = useState(0);

  const resetCamera = () => {
    setResetCounter((prev) => prev + 1);
  };

  return (
    <WebViewRedirectionBoundary>
      <div className="wrap bgw">
        <div className="content sub full-height">
          <QrScanContainer>
            <ErrorBoundary fallback={CameraErrorFallback} onReset={resetCamera}>
              <Suspense fallback={<FullScreenLoading />}>
                <QRScanCamera key={`${resetCounter}`} />
              </Suspense>
            </ErrorBoundary>
            <QrScanGuide />
          </QrScanContainer>
        </div>
      </div>
    </WebViewRedirectionBoundary>
  );
};
