import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type Props = {
  message: string;
  onConfirmClick: () => void | Promise<void>;
};

export const QRScanErrorDialog = ({ message, onConfirmClick }: Props) => {
  return overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
    return (
      <Dialog afterLeave={unmount} open={isOpen} onClose={close} message={message} onConfirmClick={onConfirmClick} />
    );
  });
};
